**✅ 正确案例：硬件代理模式**
```c
// 硬件抽象层
typedef struct {
    void (*init)(void);
    void (*write)(uint8_t data);
    uint8_t (*read)(void);
} HardwareProxy;
// SPI代理实现
void SPI_Init(void) { /* SPI初始化 */ }
void SPI_Write(uint8_t data) { /* SPI写入 */ }
uint8_t SPI_Read(void) { /* SPI读取 */ }
HardwareProxy spiProxy = {SPI_Init, SPI_Write, SPI_Read};
// 使用代理
spiProxy.init();
spiProxy.write(0x55);
```
**❌ 错误案例：直接访问硬件**
```c
// 直接操作寄存器 - 问题：移植困难
*(volatile uint32_t*)SPI_BASE_ADDR = 0x55; // 硬件依赖
// 换芯片需要改所有直接访问代码
```

**✅ 正确案例：守护模式**
```c
// 使用互斥锁保护共享数据
Mutex dataMutex;
SharedData sharedData;
void Task1_UpdateData(void) {
    mutex_lock(&dataMutex);
    sharedData.value = computeValue();
    mutex_unlock(&dataMutex);
}
void Task2_ReadData(void) {
    mutex_lock(&dataMutex);
    processValue(sharedData.value);
    mutex_unlock(&dataMutex);
}
```
**❌ 错误案例：无保护直接访问**
```c
// 问题：竞态条件
SharedData sharedData; // 无锁保护
void Task1_UpdateData(void) {
    sharedData.value = computeValue(); // 可能被中断打断
}
void Task2_ReadData(void) {
    processValue(sharedData.value); // 可能读到不一致数据
}
```

**✅ 正确案例：状态机模式**
```c
// 按键状态机
typedef enum { IDLE, DEBOUNCE, PRESS, RELEASE } KeyState;
KeyState keyState = IDLE;
uint32_t debounceTimer = 0;
void Key_ProcessEvent(KeyEvent event) {
    switch (keyState) {
        case IDLE:
            if (event == KEY_DOWN) {
                keyState = DEBOUNCE;
                debounceTimer = 0;
            }
            break;
        case DEBOUNCE:
            if (debounceTimer++ > DEBOUNCE_TIME) {
                keyState = PRESS;
                onKeyPress();
            }
            break;
        case PRESS:
            if (event == KEY_UP) {
                keyState = RELEASE;
            }
            break;
        case RELEASE:
            // ...
            break;
    }
}
```
