**✅ 正确案例：内存池模式**
```c
// 预分配内存池
typedef struct {
    uint8_t data[POOL_BLOCK_SIZE];
    bool inUse;
} MemoryBlock;
MemoryBlock memoryPool[MAX_BLOCKS];
void* Pool_Allocate(void) {
    for (int i = 0; i < MAX_BLOCKS; i++) {
        if (!memoryPool[i].inUse) {
            memoryPool[i].inUse = true;
            return &memoryPool[i].data;
        }
    }
    return NULL; // 池耗尽
}
void Pool_Free(void* ptr) {
    // O(1)释放，无碎片
    MemoryBlock* block = (MemoryBlock*)ptr;
    block->inUse = false;
}
```
